#include "ObsessionRuntime.hpp"
namespace elysium::fortress {bool ObsessionRuntime::begin(Obsession o,std::string&w){if(!o.id||!o.citizen){w="invalid obsession";return false;}return rows_.emplace(o.id,std::move(o)).second;}bool ObsessionRuntime::claim(StableId id,StableId ws,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown obsession";return false;}auto c=workshopClaims_.find(ws);if(c!=workshopClaims_.end()&&c->second!=id){w="workshop already claimed";return false;}workshopClaims_[ws]=id;i->second.workshop=ws;i->second.state=ObsessionState::ClaimWorkshop;return true;}bool ObsessionRuntime::advance(StableId id,ObsessionState s,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown obsession";return false;}if(std::uint8_t(s)<std::uint8_t(i->second.state)){w="state regression";return false;}i->second.state=s;return true;}bool ObsessionRuntime::release(StableId id,std::string&w){auto i=rows_.find(id);if(i==rows_.end()){w="unknown obsession";return false;}if(i->second.workshop)workshopClaims_.erase(i->second.workshop);i->second.workshop=0;return true;}}
